find-the-difference:
class Solution:
    def findTheDifference(self, s: str, t: str) -> str:
        r = 0
        for c in s + t:
            r ^= ord(c)
        return chr(r)

sum-of-all-odd-length-subarrays:
class Solution:
    def sumOddLengthSubarrays(self, arr: List[int]) -> int:
        n = len(arr)
        ans = 0
        for i in range(n):
            for l in range(1, n-i+1, 2):
                ans += sum(arr[i:i+l])
        return ans

count-operations-to-obtain-zero:
class Solution:
    def countOperations(self, num1: int, num2: int) -> int:
        ans = 0
        while num1 and num2:
            if num1 >= num2: num1 -= num2
            else: num2 -= num1
            ans += 1
        return ans

the-k-weakest-rows-in-a-matrix:
class Solution:
    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:
        strength = [(row.count(1), i) for i, row in enumerate(mat)]
        strength.sort()
        return [i for _, i in strength[:k]]

kth-distinct-string-in-an-array:
class Solution:
    def kthDistinct(self, arr: List[str], k: int) -> str:
        from collections import Counter
        c = Counter(arr)
        distinct = [s for s in arr if c[s] == 1]
        return distinct[k-1] if k <= len(distinct) else ""

check-whether-two-strings-are-almost-equ:
class Solution:
    def checkAlmostEquivalent(self, word1: str, word2: str) -> bool:
        from collections import Counter
        c1 = Counter(word1); c2 = Counter(word2)
        for c in set(word1) | set(word2):
            if abs(c1[c] - c2[c]) > 3: return False
        return True

find-the-town-judge:
class Solution:
    def findJudge(self, n: int, trust: List[List[int]]) -> int:
        indeg = [0]*(n+1)
        outdeg = [0]*(n+1)
        for a, b in trust:
            outdeg[a] += 1
            indeg[b] += 1
        for i in range(1, n+1):
            if indeg[i] == n-1 and outdeg[i] == 0:
                return i
        return -1

n-repeated-element-in-size-2n-array:
class Solution:
    def repeatedNTimes(self, nums: List[int]) -> int:
        seen = set()
        for x in nums:
            if x in seen: return x
            seen.add(x)
        return -1

last-stone-weight:
class Solution:
    def lastStoneWeight(self, stones: List[int]) -> int:
        import heapq
        stones = [-s for s in stones]
        heapq.heapify(stones)
        while len(stones) > 1:
            a = -heapq.heappop(stones)
            b = -heapq.heappop(stones)
            if a != b:
                heapq.heappush(stones, -(a-b))
        return -stones[0] if stones else 0

find-common-characters:
class Solution:
    def commonChars(self, words: List[str]) -> List[str]:
        from collections import Counter
        res = Counter(words[0])
        for w in words[1:]:
            res &= Counter(w)
        return list(res.elements())

uncommon-words-from-two-sentences:
class Solution:
    def uncommonFromSentences(self, s1: str, s2: str) -> List[str]:
        from collections import Counter
        c = Counter((s1 + ' ' + s2).split())
        return [w for w, n in c.items() if n == 1]

island-perimeter:
class Solution:
    def islandPerimeter(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        peri = 0
        for i in range(R):
            for j in range(C):
                if grid[i][j] == 1:
                    peri += 4
                    for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        ni, nj = i+di, j+dj
                        if 0 <= ni < R and 0 <= nj < C and grid[ni][nj] == 1:
                            peri -= 1
        return peri
